export default function Materiais(){return <main style={{padding:32,fontFamily:'Arial'}}><h1>Materiais</h1><p>Catálogo de materiais, custos, unidades, rendimentos e histórico de preços.</p><button>Novo material</button><table style={{marginTop:24,width:'100%',maxWidth:850,borderCollapse:'collapse'}}><thead><tr><th align="left">Material</th><th>Unidade</th><th>Custo</th><th>Rendimento</th></tr></thead><tbody>{materiais.map(m=><tr key={m[0]}>{m.map((x,i)=><td key={i} style={{padding:12,borderBottom:'1px solid #ddd',textAlign:i?'center':'left'}}>{x}</td>)}</tr>)}</tbody></table></main>}
